import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"二进制安全与逆向","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/二进制安全与逆向.md","filePath":"安全方向/二进制安全与逆向.md","lastUpdated":1792430298000}'),i={name:"安全方向/二进制安全与逆向.md"};function d(o,t,h,n,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="二进制安全与逆向" tabindex="-1">二进制安全与逆向 <a class="header-anchor" href="#二进制安全与逆向" aria-label="Permalink to &quot;二进制安全与逆向&quot;">​</a></h1><blockquote><p>网安最「硬核」的方向之一。校内对应「软件安全」（第 5 学期，核心课）、「软件逆向工程」以及汇编语言课程。漏洞挖掘、病毒分析、CTF Pwn/Reverse 都在这里。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>真正理解漏洞（缓冲区溢出、UAF、ROP）必须回到二进制层面；</li><li>恶意代码分析（<a href="./恶意代码分析.html">恶意代码分析</a>）的前提是逆向能力；</li><li>大厂安全研究员、漏洞挖掘岗位的核心技能。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/汇编语言.html">汇编语言</a>、<a href="./../专业基础/计算机组成与系统结构.html">计算机组成与系统结构</a></li><li><a href="./../专业基础/程序设计基础.html">程序设计基础</a>（C 语言、指针）</li><li>工具见 <a href="./../必学工具/逆向工具链.html">逆向工具链</a></li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>逆向基础：反汇编、反编译、调试、脱壳</li><li>漏洞原理：栈溢出、堆溢出、UAF、整数溢出、格式化字符串</li><li>利用技术：ROP、ret2libc、Shellcode</li><li>防护与绕过：NX/DEP、ASLR、PIE、Canary、SELinux/沙箱概念</li><li>漏洞挖掘入门：Fuzzing 概念（AFL 等）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《0day 安全：软件漏洞分析技术》</td><td>书</td><td>漏洞利用中文经典</td></tr><tr><td>《加密与解密》（第 4 版）</td><td>书</td><td>逆向综合经典</td></tr><tr><td><a href="https://pwn.college/" target="_blank" rel="noreferrer">pwn.college</a></td><td>在线课程</td><td>从零到一的程序分析/利用课程，附自动评测</td></tr><tr><td><a href="https://ctf-wiki.org/" target="_blank" rel="noreferrer">CTF-Wiki Pwn/Reverse 模块</a></td><td>知识库</td><td>系统化知识整理</td></tr><tr><td>Exploit Education（<a href="https://exploit.education/" target="_blank" rel="noreferrer">exploit.education</a>）</td><td>练习</td><td>漏洞利用实验环境</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>顺序</strong>：汇编 → 栈原理 → 第一个缓冲区溢出 → ROP → 堆 → 防护绕过；</li><li>大量练习：BUUCTF 的 Pwn/Reverse 入门题带题解，pwn.college 有自动评分；</li><li>校内「软件安全」课程认真跟，配套实验反复做；</li><li>逆向讲究手感，保持每周几题的频率比突击有效得多。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>软件安全（第 5 学期，核心课）</li><li>软件逆向工程（主干课程）</li><li>汇编语言（第 4 学期，核心课）</li></ul>',14)])])}const f=a(i,[["render",d]]);export{_ as __pageData,f as default};
